// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/$Resources/{entityType}", wrapper.ListEntities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/$namespaceinfo", wrapper.NamespaceGet)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/{entityName}", wrapper.EntityDelete)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{entityName}", wrapper.EntityGet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/{entityName}", wrapper.EntityPut)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{topicName}/subscriptions", wrapper.ListSubscriptions)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}", wrapper.SubscriptionDelete)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}", wrapper.SubscriptionGet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}", wrapper.SubscriptionPut)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}/rules", wrapper.ListRules)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}/rules/{ruleName}", wrapper.RuleDelete)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}/rules/{ruleName}", wrapper.RuleGet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/{topicName}/subscriptions/{subscriptionName}/rules/{ruleName}", wrapper.RulePut)

	return m
}
